package com.lolfm.simulator;import static org.assertj.core.api.Assertions.*;import com.lolfm.domain.Position;import java.util.*;import org.junit.jupiter.api.Test;
class ProgressionGoldIntegrationTest{private GameState s(){return LateGameTestSupport.state();}
@Test void passiveFarmAndDirectRewardsAccumulateEarnedGold(){GameState s=s();PlayerState p=s.getBlueTeamState().playerAt(Position.TOP);new GoldAwardService().awardGold(s.getBlueTeamState(),p,20,GoldSource.PASSIVE,false,10);new GoldAwardService().awardGold(s.getBlueTeamState(),p,40,GoldSource.FARM,false,10);assertThat(p.getProgressionState().getProgressionEarnedGold()).isEqualTo(60);}
@Test void killAssistAndShutdownUseActualAmountsOnce(){GameState s=s();PlayerState k=s.getBlueTeamState().playerAt(Position.MID),a=s.getBlueTeamState().playerAt(Position.JUNGLE),v=s.getRedTeamState().playerAt(Position.MID);new KillRewardResolver().award(300,s.getBlueTeamState(),k,s.getRedTeamState(),v,List.of(a),20,false,0,new ArrayList<>());assertThat(k.getProgressionState().getProgressionEarnedGold()).isEqualTo(400);assertThat(a.getProgressionState().getProgressionEarnedGold()).isEqualTo(150);assertThat(k.getProgressionState().getTotalExperience()).isEqualTo(180);assertThat(a.getProgressionState().getTotalExperience()).isEqualTo(90);}
@Test void structureRewardCreditsEachPlayerOnce(){GameState s=s();new StructureResolver().destroyNextTower(s,TeamSide.BLUE,Lane.TOP,PushReason.MACRO_PLAY);for(PlayerState p:s.getBlueTeamState().getPlayers())assertThat(p.getProgressionState().getProgressionEarnedGold()).isEqualTo(125);}
@Test void objectiveRewardCreditsEachPlayerOnce(){GameState s=s();s.advanceTimeSeconds(300);new ObjectiveResolver().updateSpawnState(s);new ObjectiveResolver().captureDragon(s,TeamSide.BLUE,300,DragonCaptureSource.GENERAL,"x");for(PlayerState p:s.getBlueTeamState().getPlayers())assertThat(p.getProgressionState().getProgressionEarnedGold()).isEqualTo(ObjectiveRuleConfig.DRAGON_GOLD_PER_PLAYER);}
@Test void zeroAndNegativeRewardAreNoOp(){PlayerState p=s().getBlueTeamState().playerAt(Position.TOP);p.addGold(0,GoldSource.OTHER,0);p.addGold(-10,GoldSource.OTHER,0);assertThat(p.getProgressionState().getProgressionEarnedGold()).isZero();}
}
